            },
          };
          const items = [textItem1, textItem2, textItem3, textItem4];
          const submitButton = {
            name: 'submit-button',
            caption: 'Подтвердить',
            icon: 'check-mark',
            onClick: form => {
                resolve();
                ESS.dialogs.closeDialog(dialogId)
            },
            isPrimary: true,
          };
          const cancelButton = {
              name: 'cancel-button',
              caption: 'Отменить',
              icon: 'cross',
              onClick: form => {
                ESS.dialogs.closeDialog(dialogId);
              },
            };
          const buttons = [submitButton, cancelButton];
          ESS.dialogs.createDialog({
              id: dialogId,
              title: 'Подтвердите действие',
              items,
              buttons,
              properties: {
                height: '200px',
              },
              closeHandler: () => {
                reject();
                ESS.dialogs.closeDialog(dialogId);
              },
          });
        }).then(results => {
          var attachmentGroup = 'StatementAttachmentGroup';
          var serviceUrl = `/api/functions/GetEmployeeCertificates`;
          ESS.network.sendRequest(serviceUrl)
            .then(function (certs) {
              var callback = function callback() {
                ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
                  .then(function (isAssignmentInProcess) {
                    if (isAssignmentInProcess) {
                      var isAssignmentBlocked = ESS.network.sendRequest(`/api/functions/IsAssignmentCardBlocked?assignmentId=${data.id}`);
                      isAssignmentBlocked
                        .then(message => {
                          if (!message) {
                            ESS.actions.workProcessActions.changeWorkItemState(data, 'Complete', 'Sign').then(function () {
