                  }).catch(function (err) {
                    ESS.toasts.showErrorToastWithLog(err);
                  });            
              };
              
              var documents = [];
              var documentGroups = data.attachments.filter(function (x) {
                return x.group === attachmentGroup;
              });
              documentGroups.forEach(function (a) {
                return documents.push({ id: a.id, title: a.title });
              });

              ESS.network.sendRequest(`/api/functions/CheckAssignmentInProcess?assignmentId=${data.id}`)
